// تصنيف مستويات الصعوبة
export const getRandomQuestion = (category, difficulty) => {
    try {
      // تحويل مستوى الصعوبة من الإنجليزية إلى العربية
      const difficultyInArabic = {
        'easy': 'سهل',
        'medium': 'متوسط',
        'hard': 'صعب'
      }[difficulty];
  
      // فلترة الأسئلة حسب الفئة ومستوى الصعوبة
      const availableQuestions = questions.filter(q => 
        q.category === category && 
        q.difficulty === difficultyInArabic &&
        !q.isDisabled // تجاهل الأسئلة المعطلة
      );
  
      if (!availableQuestions.length) {
        console.error(`لا توجد أسئلة متاحة للفئة ${category} والمستوى ${difficultyInArabic}`);
        return null;
      }
  
      // اختيار سؤال عشوائي
      const randomIndex = Math.floor(Math.random() * availableQuestions.length);
      const selectedQuestion = availableQuestions[randomIndex];
      
      return {
        ...selectedQuestion,
        index: randomIndex
      };
    } catch (error) {
      console.error('Error getting random question:', error);
      return null;
    }
  };